int main() {
    int n, t;
    cin >> n >> t;
    if (n < 3) {
        cout << 0 << endl;
        return 0;
    }

    // dp[pos][prev_y][humps][dips][last_dir]
    // last_dir: -1 = down, 1 = up, 0 = none (only at pos=1)
    long long dp[21][5][11][11][3];
    memset(dp, 0, sizeof(dp));

    // Base case: position 1, y1 can be 1..4
    for (int y = 1; y <= 4; ++y) {
        dp[1][y][0][0][0] = 1;
    }

    for (int pos = 1; pos < n; ++pos) {
        for (int prev_y = 1; prev_y <= 4; ++prev_y) {
            for (int humps = 0; humps <= t; ++humps) {
                for (int dips = 0; dips <= t - 1; ++dips) {
                    for (int last_dir = 0; last_dir <= 2; ++last_dir) {
                        if (dp[pos][prev_y][humps][dips][last_dir] == 0) continue;

                        for (int curr_y = 1; curr_y <= 4; ++curr_y) {
                            if (curr_y == prev_y) continue; // no horizontal segments

                            int new_dir = (curr_y > prev_y) ? 1 : -1;
                            int new_humps = humps;
                            int new_dips = dips;

                            if (pos >= 2) {
                                // Check if previous direction was opposite to current
                                if (last_dir == 1 && new_dir == -1) {
                                    // Peak at pos
                                    new_humps++;
                                } else if (last_dir == -1 && new_dir == 1) {
                                    // Valley at pos
                                    new_dips++;
                                }
                            }

                            if (new_humps > t || new_dips > t - 1) continue;

                            int new_last_dir = (new_dir == 1) ? 1 : 2;
                            dp[pos + 1][curr_y][new_humps][new_dips][new_last_dir] +=
                                dp[pos][prev_y][humps][dips][last_dir];
                        }
                    }
                }
            }
        }
    }

    long long ans = 0;
    for (int y = 1; y <= 4; ++y) {
        for (int last_dir = 1; last_dir <= 2; ++last_dir) {
            ans += dp[n][y][t][t - 1][last_dir];
        }
    }

    cout << ans << endl;
    return 0;
}
