int n, t;
long long dp[21][5][5][11][11];

long long solve(int pos, int prev_y, int curr_y, int peaks, int valleys) {
    if (pos == n) {
        return (peaks == t && valleys == t - 1) ? 1 : 0;
    }
    if (dp[pos][prev_y][curr_y][peaks][valleys] != -1) {
        return dp[pos][prev_y][curr_y][peaks][valleys];
    }
    long long res = 0;
    for (int next_y = 1; next_y <= 4; next_y++) {
        if (next_y == curr_y) continue;
        int new_peaks = peaks;
        int new_valleys = valleys;
        if (pos >= 2) {
            if (prev_y < curr_y && curr_y > next_y) {
                new_peaks++;
            } else if (prev_y > curr_y && curr_y < next_y) {
                new_valleys++;
            }
        }
        if (new_peaks > t || new_valleys > t - 1) continue;
        res += solve(pos + 1, curr_y, next_y, new_peaks, new_valleys);
    }
    return dp[pos][prev_y][curr_y][peaks][valleys] = res;
}

int main() {
    cin >> n >> t;
    memset(dp, -1, sizeof(dp));
    long long ans = 0;
    for (int y1 = 1; y1 <= 4; y1++) {
        for (int y2 = 1; y2 <= 4; y2++) {
            if (y1 == y2) continue;
            ans += solve(2, y1, y2, 0, 0);
        }
    }
    cout << ans << endl;
    return 0;
