long long solve(int pos, int prev_y, int humps, int valleys, int last_dir) {
    if (humps > t || valleys > t - 1) return 0;
    if (pos == n) {
        return (humps == t && valleys == t - 1) ? 1 : 0;
    }
    long long &res = dp[pos][prev_y][humps][valleys][last_dir];
    if (res != -1) return res;
    res = 0;
    for (int y = 0; y < 4; y++) {
        if (y == prev_y) continue;
        int dir = (y > prev_y) ? 1 : 0;
        int new_humps = humps, new_valleys = valleys;
        if (pos >= 2) {
            if (last_dir == 1 && dir == 0) new_humps++;
            if (last_dir == 0 && dir == 1) new_valleys++;
        }
        res += solve(pos + 1, y, new_humps, new_valleys, dir);
    }
    return res;
}

