    memset(dp, -1, sizeof(dp));
    long long ans = 0;
    for (int y1 = 0; y1 < 4; y1++) {
        for (int y2 = 0; y2 < 4; y2++) {
            if (y1 == y2) continue;
            int dir = (y2 > y1) ? 1 : 0;
            ans += solve(2, y2, 0, 0, dir);
        }
    }
